#pragma once
#include <stdint.h>

// AI: below section was generated by an AI
// A temporary physical-output overlay: two seconds to see the configured run,
// followed by a one-second fade. It never changes the saved lighting state.
struct LedCountPreview {
  static constexpr uint32_t HOLD_MS = 2000;
  static constexpr uint32_t FADE_MS = 1000;
  static constexpr uint8_t LEVEL = 48;
  uint32_t startedAt = 0;
  bool active = false;
  int16_t level = -1; // -1 means normal rendering; 0 is the final black frame

  void start(uint32_t now) {
    startedAt = now;
    active = true;
    level = LEVEL;
  }

  // Unsigned elapsed time also handles the millis() rollover. Leave one black
  // frame at the end before resuming the underlying effect or live stream.
  void update(uint32_t now) {
    if (!active) { level = -1; return; }
    const uint32_t elapsed = now - startedAt;
    if (elapsed < HOLD_MS) level = LEVEL;
    else if (elapsed < HOLD_MS + FADE_MS)
      level = (LEVEL * (HOLD_MS + FADE_MS - elapsed)) / FADE_MS;
    else { active = false; level = 0; }
  }
  bool needsFrame() const { return active || level >= 0; }
};
// AI: end
